def unanomize(user):
	return unanomize_user_dic[user]

def frameToStamp(frame, offset=0):
	time = float(frame)/float(FRAMERATE)+offset
	seconds = int(math.floor(time))
	minutes = seconds // 60
	miliseconds = time - seconds
	miliseconds *= 1000
	miliseconds = int(miliseconds)
	seconds = seconds % 60
	timestamp = f"{minutes:02d}{seconds:02d}{miliseconds:03d}"
	#print(timestamp)
	return timestamp
 
 
